using System.Text.Json;
using AeroScience.Missions;
using AeroScience.Shared;
using Microsoft.EntityFrameworkCore;
namespace AeroScience.Organization;

// Rebuildable index only. P15 publication/claim and P17/P18 receipt/findings stay authoritative.
public sealed class CampaignProgressProjection(OrganizationDatabase db,OrganizationManagement history,CampaignCoverageProjection coverage)
{
    public const int Version=1;
    static T Read<T>(string json)=>JsonSerializer.Deserialize<T>(json,WireJson.Options)??throw new InvalidOperationException("Progress source unavailable.");
    public static void Index(OpportunityRecord row,OrganizationOpportunitySnapshot value){row.ProgressIndexVersion=Version;row.PublishedName=value.Name;row.PublishedSearchName=value.Name.ToUpperInvariant();row.PublishedRequiredPilots=value.Policy.RequiredDistinctPilots;row.PublishedSha256=PreflightReadiness.Hash(value);}
    public static void Index(CampaignRecord row,OrganizationCampaignView value){row.ProgressIndexVersion=Version;row.PublishedName=value.Name;row.PublishedSearchName=value.Name.ToUpperInvariant();row.PublishedObjective=value.Objective;}
    public async Task Backfill(CancellationToken ct)
    {
        while(true){var ids=await db.Campaigns.AsNoTracking().Where(r=>r.PublishedRevision!=null&&r.ProgressIndexVersion!=Version).OrderBy(r=>r.Id).Select(r=>r.Id).Take(20).ToArrayAsync(ct);if(ids.Length==0)break;foreach(var id in ids){var row=await db.Campaigns.SingleAsync(r=>r.Id==id,ct);if(row.ProgressIndexVersion>Version)throw new InvalidOperationException("A newer progress index cannot be downgraded.");Index(row,Read<OrganizationCampaignView>((await history.ReadRevision(id,row.PublishedRevision!.Value,ct)).SnapshotJson));}await db.SaveChangesAsync(ct);db.ChangeTracker.Clear();}
        while(true){var ids=await db.Opportunities.AsNoTracking().Where(r=>r.PublishedRevision!=null&&r.ProgressIndexVersion!=Version).OrderBy(r=>r.Id).Select(r=>r.Id).Take(20).ToArrayAsync(ct);if(ids.Length==0)break;foreach(var id in ids){var row=await db.Opportunities.SingleAsync(r=>r.Id==id,ct);if(row.ProgressIndexVersion>Version)throw new InvalidOperationException("A newer progress index cannot be downgraded.");var source=await history.ReadRevision(id,row.PublishedRevision!.Value,ct);var value=Read<OrganizationOpportunitySnapshot>(source.SnapshotJson);if(value.Status!=OrganizationPublication.Published||PreflightReadiness.Hash(value)!=source.Sha256)throw new InvalidOperationException("Publication index failed its original hash check.");Index(row,value);}await db.SaveChangesAsync(ct);db.ChangeTracker.Clear();}
        while(true){var ids=await db.Reviews.AsNoTracking().Where(r=>!db.CampaignProjections.Any(p=>p.RootId==r.Id&&p.Version==Version&&p.ReviewRevision==r.Revision&&p.HeadSha256==r.HeadSha256)).OrderBy(r=>r.Id).Select(r=>r.Id).Take(10).ToArrayAsync(ct);if(ids.Length==0)return;foreach(var id in ids){await using var tx=await db.Database.BeginTransactionAsync(ct);await db.Database.ExecuteSqlRawAsync($"SELECT pg_advisory_xact_lock({OrganizationMembership.MembershipLock})",ct);await Sync(id,ct);await tx.CommitAsync(ct);db.ChangeTracker.Clear();}}
    }
    static ResearchReviewState State(ResearchReviewRequirementRecord[] requirements,ResearchReviewCaseRecord source)=>requirements.All(q=>q.State==ResearchReviewState.Approved)?ResearchReviewState.Approved:requirements.Any(q=>q.State==ResearchReviewState.MoreEvidenceRequested)?ResearchReviewState.MoreEvidenceRequested:requirements.Any(q=>q.State==ResearchReviewState.Rejected)?ResearchReviewState.Rejected:source.State==ResearchReviewState.UpdatedSubmission?ResearchReviewState.UpdatedSubmission:ResearchReviewState.AwaitingReview;
    internal async Task<(ReviewRequirementDefinition Definition,ReviewFinding Finding)> ApprovedFinding(ResearchReviewCaseRecord source,ResearchReviewRequirementRecord q,CancellationToken ct)
        =>await ReadApprovedFinding(db,source,q,ct);
    internal static async Task<(ReviewRequirementDefinition Definition,ReviewFinding Finding)> ReadApprovedFinding(OrganizationDatabase db,ResearchReviewCaseRecord source,ResearchReviewRequirementRecord q,CancellationToken ct)
    {
        var definition=Read<ReviewRequirementDefinition>(q.DefinitionJson);var finding=Read<ReviewFinding>(q.FindingJson??throw new InvalidOperationException("Approval has no original finding."));var row=await db.ReviewEvents.AsNoTracking().SingleOrDefaultAsync(e=>e.RootId==source.Id&&e.Id==finding.EventId,ct)??throw new InvalidOperationException("Original approval event unavailable.");var e=Read<ResearchReviewEvent>(row.PayloadJson);
        if(q.State!=ResearchReviewState.Approved||finding.State!=ResearchReviewState.Approved||e.Action!=ResearchReviewAction.Approve||e.RootReceiptId!=source.Id||e.Sequence!=finding.Sequence||e.Sequence>source.Revision||e.Target?.CardId!=q.CardId||e.Target.RequirementKey!=q.Key||e.ActorId!=finding.ReviewerId||e.TimestampUtc!=finding.TimestampUtc||e.PolicyVersion!=1||finding.PolicyVersion!=1||PreflightReadiness.Hash(e with{Sha256=""})!=row.Sha256||row.Sha256!=e.Sha256||PreflightReadiness.Hash(e.Evidence)!=PreflightReadiness.Hash(finding.Evidence))throw new InvalidOperationException("Current approved finding differs from its immutable source event.");return(definition,finding);
    }
    public async Task Sync(Guid root,CancellationToken ct,bool force=false)
    {
        var source=await db.Reviews.AsNoTracking().SingleAsync(r=>r.Id==root,ct);var marker=await db.CampaignProjections.FindAsync([root],ct);if(marker?.Version>Version)throw new InvalidOperationException("A newer progress interpretation cannot be replaced.");if(!force&&marker?.Version==Version&&marker.ReviewRevision==source.Revision&&marker.HeadSha256==source.HeadSha256){await coverage.Sync(root,ct,force);return;}
        if(marker is null){marker=new(){RootId=root};db.CampaignProjections.Add(marker);}marker.Version=Version;marker.ReviewRevision=source.Revision;marker.HeadSha256=source.HeadSha256;marker.Valid=false;
        try{
            var document=await OrganizationReviews.ReadDocument(db,root,ct);SubmissionEvidenceProtocol.Validate(document,ct);var official=SubmissionReviewEvidence.Requirements(document);var requirements=await db.ReviewRequirements.AsNoTracking().Where(q=>q.RootId==root).ToArrayAsync(ct);if(requirements.Length!=official.Length||requirements.Any(q=>!official.Any(d=>d.CardId==q.CardId&&d.Key==q.Key&&d.DefinitionSha256==Read<ReviewRequirementDefinition>(q.DefinitionJson).DefinitionSha256)))throw new InvalidOperationException("Required findings differ from the frozen received definition.");
            foreach(var binding in document.Manifest.Cards){
                ct.ThrowIfCancellationRequested();var publication=await history.ReadRevision(binding.OpportunityId,binding.IssuedRevision,ct);var published=Read<OrganizationOpportunitySnapshot>(publication.SnapshotJson);var claim=await db.Claims.AsNoTracking().SingleAsync(c=>c.Id==binding.ClaimId,ct);if(publication.Sha256!=binding.IssuedSha256||PreflightReadiness.Hash(published)!=publication.Sha256||claim.UserId!=source.PilotId||claim.IssuedSha256!=binding.IssuedSha256||claim.IssuedRevision!=binding.IssuedRevision)throw new InvalidOperationException("Original publication and claim identity do not agree.");
                var current=await db.CampaignContributions.SingleOrDefaultAsync(c=>c.RootId==root&&c.CardId==binding.CardId,ct);if(current is null){current=new(){RootId=root,CardId=binding.CardId,PilotId=source.PilotId,ClaimId=binding.ClaimId,OpportunityId=binding.OpportunityId,CampaignId=source.CampaignId,ProgramId=source.ProgramId,PublicationRevision=binding.IssuedRevision,PublicationSha256=binding.IssuedSha256,DefinitionSha256=binding.DefinitionSha256};db.CampaignContributions.Add(current);}
                if(current.PilotId!=source.PilotId||current.ClaimId!=binding.ClaimId||current.OpportunityId!=binding.OpportunityId||current.PublicationRevision!=binding.IssuedRevision||current.PublicationSha256!=binding.IssuedSha256||current.DefinitionSha256!=binding.DefinitionSha256)throw new InvalidOperationException("Derived identity cannot substitute another original claim or version.");
                var qs=requirements.Where(q=>q.CardId==binding.CardId).OrderBy(q=>q.Key,StringComparer.Ordinal).ToArray();var signature=PreflightReadiness.Hash(qs.Select(q=>new{q.Key,q.State,q.FindingJson}));var unchanged=!force&&current.Valid&&current.ApprovalSignature==signature;current.State=State(qs,source);current.ApprovedFindings=qs.Count(q=>q.State==ResearchReviewState.Approved);current.RequiredFindings=qs.Length;current.ReviewRevision=source.Revision;current.SourceHeadSha256=source.HeadSha256;current.UpdatedUtc=source.UpdatedUtc;current.AcceptancePolicyVersion=Version;current.Valid=true;
                if(unchanged)continue;
                var old=await db.CampaignMeasurements.Where(m=>m.RootId==root&&m.CardId==binding.CardId).ToArrayAsync(ct);current.SummaryJson="";current.AcceptedUtc=null;current.ApprovalSignature=signature;
                if(current.State!=ResearchReviewState.Approved){db.CampaignMeasurements.RemoveRange(old);continue;}
                try{
                    var summaries=new List<ApprovedRequirementSummary>();var groups=new List<ApprovedMeasurementSummary>();foreach(var q in qs){var accepted=await ApprovedFinding(source,q,ct);var selected=await OrganizationReviews.Selected(db,source,accepted.Finding.Evidence,binding.CardId,ct);var result=SubmissionReviewEvidence.DescribeApproved(document,selected,accepted.Definition,accepted.Finding,ct);summaries.Add(result.Requirement);groups.AddRange(result.Measurements);}
                    var acceptedAt=summaries.Max(r=>r.ApprovedUtc);var identity="Contributor "+PreflightReadiness.Hash(new{document.Manifest.OrganizationId,source.PilotId})[..12];var summary=new ApprovedResearchSummary(1,root,binding.CardId,binding.OpportunityId,binding.IssuedRevision,binding.IssuedSha256,binding.DefinitionSha256,source.CampaignId,source.CampaignName,published.Name,published.Objective,identity,acceptedAt,Version,summaries.ToArray(),["Only currently approved complete-card contributions count. Multiple attempts/submissions by this pilot count once for this exact card/publication/policy.",SubmissionEvidenceProtocol.HistoryDisclosure,"This is a sanitized derived summary of selected received evidence. Raw packages, account names, private notes, reviewer explanations and aircraft details remain restricted."]);
                    current.SummaryJson=JsonSerializer.Serialize(summary,WireJson.Options);current.AcceptedUtc=acceptedAt;var retained=groups.Select(g=>g.GroupId).ToHashSet();db.CampaignMeasurements.RemoveRange(old.Where(g=>!retained.Contains(g.GroupId)));foreach(var g in groups){var indexed=old.SingleOrDefault(m=>m.GroupId==g.GroupId);if(indexed is null){indexed=new(){RootId=root,CardId=binding.CardId,GroupId=g.GroupId};db.CampaignMeasurements.Add(indexed);}indexed.PayloadJson=JsonSerializer.Serialize(g,WireJson.Options);}
                }catch(Exception e) when(e is ArgumentException or InvalidOperationException or IOException or JsonException){current.Valid=false;current.SummaryJson="";current.AcceptedUtc=null;}
            }marker.Valid=true;
        }catch(Exception e) when(e is ArgumentException or InvalidOperationException or IOException or JsonException){var rows=await db.CampaignContributions.Where(c=>c.RootId==root).ToArrayAsync(ct);foreach(var r in rows){r.Valid=false;r.SummaryJson="";r.AcceptedUtc=null;r.ReviewRevision=source.Revision;r.SourceHeadSha256=source.HeadSha256;}marker.Valid=false;}
        await db.SaveChangesAsync(ct);await coverage.Sync(root,ct,force);
    }
}
